#!/usr/bin/env python3
"""Embed Ultralytics metadata header into TensorRT .engine generated by trtexec."""

from __future__ import annotations

import argparse
from pathlib import Path

import yaml

from unina_dla.ultralytics_wrapper import build_ultralytics_metadata, embed_metadata_in_engine


def parse_names(value: str):
    p = Path(value)
    if p.exists() and p.suffix.lower() in {".yaml", ".yml"}:
        with p.open("r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
        if isinstance(data, dict) and "names" in data:
            return data["names"]
        return data
    return [x.strip() for x in value.split(",") if x.strip()]


def parse_imgsz(value: str) -> tuple[int, int]:
    value = value.strip().lower()
    delimiter = "," if "," in value else ("x" if "x" in value else None)
    if delimiter:
        parts = [int(x.strip()) for x in value.split(delimiter) if x.strip()]
        if len(parts) != 2:
            raise ValueError("--imgsz must be an int (640) or 'w,h' (768,480).")
        if parts[0] > parts[1]:
            return (parts[1], parts[0])
        return (parts[0], parts[1])
    side = int(value)
    return (side, side)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Embed metadata in TensorRT engine for Ultralytics AutoBackend"
    )
    parser.add_argument("--engine", required=True, help="Input .engine path")
    parser.add_argument("--names", required=True, help="Class names CSV or dataset YAML path")
    parser.add_argument(
        "--output", default=None, help="Optional output .engine path (default: in-place)"
    )
    parser.add_argument("--imgsz", default="640", help="Model input size metadata: 640 or h,w")
    parser.add_argument("--stride", type=int, default=32, help="Model stride metadata")
    parser.add_argument("--batch", type=int, default=1, help="Batch size metadata")
    parser.add_argument("--channels", type=int, default=3, help="Input channels metadata")
    parser.add_argument("--dynamic", action="store_true", help="Mark metadata as dynamic batch")
    parser.add_argument("--nms", action="store_true", help="Mark metadata as NMS-enabled")
    parser.add_argument("--no-end2end", action="store_true", help="Disable end2end metadata flag")
    parser.add_argument("--dla", type=int, default=None, help="Optional DLA core metadata (0 or 1)")
    args = parser.parse_args()

    names = parse_names(args.names)
    imgsz = parse_imgsz(args.imgsz)

    metadata = build_ultralytics_metadata(
        names=names,
        imgsz=imgsz,
        stride=args.stride,
        end2end=not args.no_end2end,
        dynamic=args.dynamic,
        batch=args.batch,
        channels=args.channels,
        nms_enabled=args.nms,
        dla=args.dla,
    )

    out = embed_metadata_in_engine(args.engine, metadata=metadata, output_path=args.output)
    print(f"Engine metadata embedded: {out}")


if __name__ == "__main__":
    main()
